                    PercentageDiscount = 0,
                    AppliesToAll = Models::NewPercentageDiscountAppliesToAll.True,
                    AppliesToItemIds = ["item_1", "item_2"],
                    AppliesToPriceIds = ["price_1", "price_2"],
